#include <iostream>
#include <vector>
using namespace std;
​
// 树状数组 更新值
// 参数：tree 数组，index 更新的位置，delta 增加的值
void update(vector<long long> &tree, int index, long long delta) {
    int n = (int)tree.size() - 1;
    while (index <= n) {
        tree[index] += delta;  // 更新当前位置的值
        index += index & (-index);  // 跳到所有包含这个位置的父区间
    }
}
​
// 树状数组 查询区间和
// 参数：tree 数组，index 查询的前缀位置
// 返回值：从1到index的区间和
long long query(const vector<long long> &tree, int index) {
    long long res = 0;
    while (index > 0) {
        res += tree[index];  // 累加当前节点值
        index -= index & (-index);  // 跳到上一个区间的父区间
    }
    return res;
}
​
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
​
    int n;
    cin >> n;
​
    // 初始化四个树状数组，长度为 n+1，位置从1开始
    vector<long long> fenw0_odd(n + 1, 0);   // 全奇数序列
    vector<long long> fenw1_even(n + 1, 0);  // 全偶数序列
    vector<long long> fenw2_even(n + 1, 0);  // 奇偶交替，下一位需为奇数
    vector<long long> fenw2_odd(n + 1, 0);   // 奇偶交替，下一位需为偶数
​
    long long ans0 = 0, ans1 = 0, ans2 = 0;
​
    // 从1遍历到n
    for (int x = 1; x <= n; ++x) {
        int half = x / 2;  // 二分之一，用于查询前面结果
        if (x % 2 == 1) {  // x 是奇数
            // 查询前一半长度的奇数序列和奇偶交替序列
            long long dp0_val = query(fenw0_odd, half);
            long long dp2_val = query(fenw2_even, half);
​
            // 更新当前奇数位置的dp值
            update(fenw0_odd, x, 1 + dp0_val);
            update(fenw2_odd, x, 1 + dp2_val);
​
            // 到最后一个元素时保存答案
            if (x == n) {
                ans0 = dp0_val;
                ans2 = dp2_val;
            }
        } else {  // x 是偶数
            // 查询前一半长度的偶数序列和奇偶交替序列
            long long dp1_val = query(fenw1_even, half);
            long long dp2_val = query(fenw2_odd, half);
​
            // 更新当前偶数位置的dp值
            update(fenw1_even, x, 1 + dp1_val);
            update(fenw2_even, x, 1 + dp2_val);
​
            if (x == n) {
                ans1 = dp1_val;
                ans2 = dp2_val;
            }
        }
    }
​
    // 总序列数 = 1 + 三个状态的答案和
    cout << 1 + ans0 + ans1 + ans2 << "\n";
​
    return 0;
}
