package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
)
​
// 树状数组 更新操作，delta为int64类型
func update(tree []int64, index int, delta int64) {
    n := len(tree) - 1
    for index <= n {
        tree[index] += delta // 更新当前位置值
        index += index & (-index) // 跳到所有包含该位置的父区间
    }
}
​
// 查询区间和，返回1到index区间和
func query(tree []int64, index int) int64 {
    var res int64 = 0
    for index > 0 {
        res += tree[index] // 累加当前节点的值
        index -= index & (-index) // 跳到上一个区间
    }
    return res
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
    scanner.Scan()
    n, _ := strconv.Atoi(scanner.Text())
​
    // 初始化四个树状数组，全部用0填充，长度为n+1
    fenw0_odd := make([]int64, n+1)  // 全奇数序列
    fenw1_even := make([]int64, n+1) // 全偶数序列
    fenw2_even := make([]int64, n+1) // 奇偶交替，下一位需为奇数
    fenw2_odd := make([]int64, n+1)  // 奇偶交替，下一位需为偶数
​
    var ans0, ans1, ans2 int64
​
    // 遍历1到n
    for x := 1; x <= n; x++ {
        half := x / 2
        if x%2 == 1 { // 奇数位置
            dp0_val := query(fenw0_odd, half)  // 查询前半长度奇数序列
            dp2_val := query(fenw2_even, half) // 查询前半长度奇偶交替序列
​
            update(fenw0_odd, x, 1+dp0_val) // 更新奇数序列
            update(fenw2_odd, x, 1+dp2_val) // 更新奇偶交替序列
​
            if x == n {
                ans0 = dp0_val
                ans2 = dp2_val
            }
        } else { // 偶数位置
            dp1_val := query(fenw1_even, half) // 查询前半长度偶数序列
            dp2_val := query(fenw2_odd, half)  // 查询前半长度奇偶交替序列
​
            update(fenw1_even, x, 1+dp1_val)  // 更新偶数序列
            update(fenw2_even, x, 1+dp2_val)  // 更新奇偶交替序列
​
            if x == n {
                ans1 = dp1_val
                ans2 = dp2_val
            }
        }
    }
​
    // 输出结果：1 + 三个状态和
    fmt.Println(1 + ans0 + ans1 + ans2)
}
